<?php
$uid = (int)$u['id']; $tok = preg_replace('/[^a-f0-9]/', '', (string)($_GET['t'] ?? '')); $i = row('SELECT i.*, u.name issuer FROM invoices i JOIN users u ON u.id=i.issuer_id WHERE i.link_token=?', [$tok]);
if (!$i) { http_response_code(404); echo page_head('Pay invoice') . card('', empty_state('This payment link is not valid.')); return; }
handle('inv_pay', function () use ($uid, $tok) { Auth::verifyPin($uid, (string)($_POST['pin'] ?? '')); $r = Invoices::pay($uid, $tok, cents($_POST['amount'] ?? ''), idem_key()); if ($r['status'] === 'approval_pending') return 'Payment needs approval before it is sent.'; flash('ok', 'Payment received and reconciled against the invoice.'); redirect(url('receipt', ['ref' => $r['ref']])); });
$t = Invoices::totals((int)$i['id']); $cur = $i['currency']; $open = !in_array($i['status'], ['paid', 'cancelled', 'draft'], true) && $t['due_c'] > 0 && (int)$i['issuer_id'] !== $uid;
echo page_head('Pay invoice', $i['number'] . ' from ' . $i['issuer']) . '<div class="grid g2">' . card($i['title'], '<dl class="kv"><dt>Status</dt><dd>' . badge($i['status']) . '</dd><dt>Due date</dt><dd>' . e(fdate($i['due_date'], false)) . '</dd><dt>Invoice total</dt><dd>' . mny(dec($t['total_c']), $cur) . '</dd><dt>Already paid</dt><dd>' . mny(dec($t['paid_c']), $cur) . '</dd></dl><div class="total-row"><span>Outstanding</span><span>' . mny(dec($t['due_c']), $cur) . '</span></div><p class="hint">The fee is paid by the issuer, not by you.</p>') .
  card('Payment', $open ? form_start('inv_pay') . field('Amount to pay now', 'amount', 'text', dec($t['due_c']), 'required inputmode="decimal"', 'You may pay part of the outstanding amount.') . pin_field() . btn('Pay now') . '</form>' : '<p class="muted">' . ((int)$i['issuer_id'] === $uid ? 'You issued this invoice.' : 'This invoice cannot be paid right now.') . '</p>') . '</div>';
